#include <zephyr/ztest.h>
#include <zephyr/storage/stream_flash.h>
#include <zephyr/drivers/flash.h>
#include <zephyr/devicetree.h>
#include <string.h>
#include <stdio.h>

#define TEST_FLASH_SIZE (256 * 1024) /* 256 KB */
#define TEST_FLASH_ERASE_BLOCK_SIZE (4 * 1024) /* 4 KB */
#define TEST_FLASH_WRITE_BLOCK_SIZE 1 /* Smallest write unit */

/* Mock flash device data */
static uint8_t mock_flash_storage[TEST_FLASH_SIZE];

static int mock_flash_read(const struct device *dev, off_t offset, void *data, size_t len)
{
    if (offset + len > TEST_FLASH_SIZE) {
        return -EINVAL;
    }
    memcpy(data, &mock_flash_storage[offset], len);
    return 0;
}

static int mock_flash_write(const struct device *dev, off_t offset, const void *data, size_t len)
{
    if (offset + len > TEST_FLASH_SIZE) {
        return -EINVAL;
    }
    memcpy(&mock_flash_storage[offset], data, len);
    return 0;
}

static int mock_flash_erase(const struct device *dev, off_t offset, size_t size)
{
    if (offset + size > TEST_FLASH_SIZE || (offset % TEST_FLASH_ERASE_BLOCK_SIZE) != 0 ||
        (size % TEST_FLASH_ERASE_BLOCK_SIZE) != 0) {
        return -EINVAL;
    }
    memset(&mock_flash_storage[offset], 0xFF, size);
    return 0;
}

static int mock_flash_get_parameters(const struct device *dev, struct flash_parameters *params)
{
    params->write_block_size = TEST_FLASH_WRITE_BLOCK_SIZE;
    params->erase_block_size = TEST_FLASH_ERASE_BLOCK_SIZE;
    params->size = TEST_FLASH_SIZE;
    return 0;
}

static const struct flash_driver_api mock_flash_api = {
    .read = mock_flash_read,
    .write = mock_flash_write,
    .erase = mock_flash_erase,
    .get_parameters = mock_flash_get_parameters,
};

DEVICE_DEFINE(mock_flash_dev, "mock_flash", NULL, NULL, NULL, NULL, POST_KERNEL, 0, &mock_flash_api);

static const struct device *flash_dev;
static struct stream_flash_ctx stream_flash_ctx;

#define STREAM_FLASH_TEST_PARTITION_OFFSET 0x0
#define STREAM_FLASH_TEST_PARTITION_SIZE   (TEST_FLASH_SIZE)

static void test_stream_flash_setup(void)
{
    flash_dev = DEVICE_GET(mock_flash_dev);
    zassert_true(device_is_ready(flash_dev), "Mock flash device not ready");

    int rc = stream_flash_init(&stream_flash_ctx, flash_dev);
    zassert_equal(rc, 0, "stream_flash_init failed with %d", rc);

    /* Erase the entire mock flash for a clean state */
    rc = flash_erase(flash_dev, STREAM_FLASH_TEST_PARTITION_OFFSET, STREAM_FLASH_TEST_PARTITION_SIZE);
    zassert_equal(rc, 0, "Flash erase failed with %d", rc);
}

static void test_stream_flash_teardown(void)
{
    /* Nothing specific to tear down for this mock */
}

ZTEST_SUITE(lib_stream_flash, NULL, NULL, test_stream_flash_setup, test_stream_flash_teardown, NULL);

/* Test cases from the original main.c, adapted to use the mock flash */

/* Test that buffer size greater than page size is handled correctly */
ZTEST(lib_stream_flash, test_stream_flash_buf_size_greater_than_page_size)
{
    uint8_t write_buf[TEST_FLASH_ERASE_BLOCK_SIZE * 2]; /* Larger than page */
    uint8_t read_buf[sizeof(write_buf)];
    int rc;

    memset(write_buf, 0xAA, sizeof(write_buf));

    rc = stream_flash_buffered_write(&stream_flash_ctx, write_buf, sizeof(write_buf), false);
    zassert_equal(rc, 0, "Buffered write failed with %d", rc);

    rc = stream_flash_buffered_write_flush(&stream_flash_ctx);
    zassert_equal(rc, 0, "Flush failed with %d", rc);

    rc = flash_read(flash_dev, STREAM_FLASH_TEST_PARTITION_OFFSET, read_buf, sizeof(read_buf));
    zassert_equal(rc, 0, "Flash read failed with %d", rc);

    zassert_mem_equal(write_buf, read_buf, sizeof(write_buf), "Data mismatch");
}

/* Test basic buffered write functionality */
ZTEST(lib_stream_flash, test_stream_flash_buffered_write)
{
    uint8_t write_buf[64];
    uint8_t read_buf[sizeof(write_buf)];
    int rc;

    memset(write_buf, 0xBB, sizeof(write_buf));

    rc = stream_flash_buffered_write(&stream_flash_ctx, write_buf, sizeof(write_buf), false);
    zassert_equal(rc, 0, "Buffered write failed with %d", rc);

    rc = stream_flash_buffered_write_flush(&stream_flash_ctx);
    zassert_equal(rc, 0, "Flush failed with %d", rc);

    rc = flash_read(flash_dev, STREAM_FLASH_TEST_PARTITION_OFFSET, read_buf, sizeof(read_buf));
    zassert_equal(rc, 0, "Flash read failed with %d", rc);

    zassert_mem_equal(write_buf, read_buf, sizeof(read_buf), "Data mismatch");
}

/* Test buffered write with available limit */
ZTEST(lib_stream_flash, test_stream_flash_buffered_write_available_limit)
{
    uint8_t write_buf[TEST_FLASH_SIZE + 1]; /* One byte more than flash size */
    int rc;

    memset(write_buf, 0xCC, sizeof(write_buf));

    /* Attempt to write more data than available flash size */
    rc = stream_flash_buffered_write(&stream_flash_ctx, write_buf, sizeof(write_buf), false);
    /* Expect -ENOMEM or similar error indicating no space */
    zassert_not_equal(rc, 0, "Expected write to fail, but it succeeded");
    zassert_equal(rc, -ENOMEM, "Expected -ENOMEM, got %d", rc);

    /* Flush should also fail or indicate no data to flush if previous write failed */
    rc = stream_flash_buffered_write_flush(&stream_flash_ctx);
    /* Depending on implementation, flush might return 0 if nothing was buffered, or an error */
    /* For this test, we primarily care about the buffered_write failure */
    if (rc != 0) {
        LOG_INF("Flush returned %d after failed write attempt", rc);
    }
}

/* Add more test cases as needed, e.g., for stream_flash_read, etc. */

/* Example of a stream_flash_read test */
ZTEST(lib_stream_flash, test_stream_flash_read)
{
    uint8_t write_data[128];
    uint8_t read_data[128];
    uint8_t stream_read_data[128];
    int rc;

    /* Prepare data to write */
    for (int i = 0; i < sizeof(write_data); i++) {
        write_data[i] = i;
    }

    /* Erase and write directly to flash for known state */
    rc = flash_erase(flash_dev, STREAM_FLASH_TEST_PARTITION_OFFSET, TEST_FLASH_ERASE_BLOCK_SIZE);
    zassert_equal(rc, 0, "Flash erase failed with %d", rc);

    rc = flash_write(flash_dev, STREAM_FLASH_TEST_PARTITION_OFFSET, write_data, sizeof(write_data));
    zassert_equal(rc, 0, "Flash write failed with %d", rc);

    /* Read using stream_flash_read */
    rc = stream_flash_read(&stream_flash_ctx, STREAM_FLASH_TEST_PARTITION_OFFSET, stream_read_data, sizeof(stream_read_data));
    zassert_equal(rc, 0, "stream_flash_read failed with %d", rc);

    zassert_mem_equal(write_data, stream_read_data, sizeof(write_data), "Stream read data mismatch");

    /* Verify direct flash read as well */
    rc = flash_read(flash_dev, STREAM_FLASH_TEST_PARTITION_OFFSET, read_data, sizeof(read_data));
    zassert_equal(rc, 0, "Flash read failed with %d", rc);
    zassert_mem_equal(write_data, read_data, sizeof(write_data), "Direct read data mismatch");
}
